    // Fetch both edges at once using bilinear filtering:
    e = texture(tEdges, coord.xy).rg; // LinearSampler
    e = SMAADecodeDiagBilinearAccess(e);

    // Non-optimized version:
    // e.g = texture(tEdges, coord.xy).g; // LinearSampler
    // e.r = SMAASampleLevelZeroOffset(tEdges, coord.xy, vec2(1, 0)).r;

